mapper.select:
SELECT * FROM ( SELECT ROWNUM AS rnum, a.* FROM ( SELECT r.routepost_id AS routepostId, r.user_id AS userId, u.nickname AS nickname, r.routepost_title AS routepostTitle, r.routepost_content AS routepostContent, r.routepost_satisfaction AS routepostSatisfaction, r.routepost_report_status AS routepostReportStatus, r.routepost_view_count AS routepostViewCount, r.routepost_report_count AS routepostReportCount, NVL(l.like_count, 0) AS likeCount, NVL(c.comment_count, 0) AS commentCount, TO_CHAR(r.routepost_regdate, 'YYYY-MM-DD HH24:MI:SS') AS routepostRegdate FROM tblRoutePost r JOIN tblUser u ON r.user_id = u.user_id LEFT JOIN ( SELECT routepost_id, COUNT(*) AS like_count FROM tblRoutePostLikes GROUP BY routepost_id ) l ON r.routepost_id = l.routepost_id LEFT JOIN ( SELECT routepost_id, COUNT(*) AS comment_count FROM tblRoutePostComment WHERE comment_status = 'A' GROUP BY routepost_id ) c ON r.routepost_id = c.routepost_id
AND LOWER(r.routepost_title) LIKE '%' || LOWER(#{keyword}) || '%'
AND LOWER(r.routepost_content) LIKE '%' || LOWER(#{keyword}) || '%'
AND LOWER(u.nickname) LIKE '%' || LOWER(#{keyword}) || '%'
AND ( LOWER(r.routepost_title) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(r.routepost_content) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(u.nickname) LIKE '%' || LOWER(#{keyword}) || '%' )
ORDER BY r.routepost_regdate DESC ) a WHERE ROWNUM <= #{end, jdbcType=NUMERIC}
) WHERE rnum >= #{start, jdbcType=NUMERIC}

mapper.update:
UPDATE tblRoutePost
SET routepost_view_count = routepost_view_count + 1
WHERE routepost_id = #{routepostId}

UPDATE tblRoutePost
SET routepost_title        = #{routepostTitle},
    routepost_content      = #{routepostContent},
    routepost_satisfaction = #{routepostSatisfaction}
WHERE routepost_id = #{routepostId}

mapper.insert:
INSERT INTO tblRoutePostImage (
    routepost_image_id,
    routepost_id,
    routepost_image_seq,
    routepost_image_url
) VALUES (
    seqRoutePostImage.NEXTVAL,
    #{routepostId},
    (
        SELECT NVL(MAX(routepost_image_seq), 0) + 1
        FROM tblRoutePostImage
        WHERE routepost_id = #{routepostId}
    ),
    #{routepostImageUrl}
)

